CREATE TABLE IF NOT EXISTS video_likes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), user_id BIGINT UNSIGNED NOT NULL, video_id BIGINT UNSIGNED NOT NULL, UNIQUE KEY idx_video_like(user_id, video_id), KEY idx_video_likes_deleted_at(deleted_at));
CREATE TABLE IF NOT EXISTS video_collections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), user_id BIGINT UNSIGNED NOT NULL, video_id BIGINT UNSIGNED NOT NULL, UNIQUE KEY idx_video_collection(user_id, video_id), KEY idx_video_collections_deleted_at(deleted_at));
CREATE TABLE IF NOT EXISTS comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), video_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, parent_id BIGINT UNSIGNED NULL, content TEXT NOT NULL, like_count BIGINT NOT NULL DEFAULT 0, KEY idx_comments_video_id(video_id), KEY idx_comments_user_id(user_id), KEY idx_comments_parent_id(parent_id), KEY idx_comments_deleted_at(deleted_at));
CREATE TABLE IF NOT EXISTS comment_likes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), user_id BIGINT UNSIGNED NOT NULL, comment_id BIGINT UNSIGNED NOT NULL, UNIQUE KEY idx_comment_like(user_id, comment_id));
CREATE TABLE IF NOT EXISTS danmaku (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), video_id BIGINT UNSIGNED NOT NULL, scene VARCHAR(20) NOT NULL DEFAULT 'video', user_id BIGINT UNSIGNED NOT NULL, content VARCHAR(500) NOT NULL, time INT NOT NULL DEFAULT 0, color VARCHAR(10), font_size VARCHAR(10), type VARCHAR(10), blocked BOOLEAN DEFAULT FALSE, KEY idx_danmaku_video_id(video_id), KEY idx_danmaku_user_id(user_id), KEY idx_danmaku_scene(scene), KEY idx_danmaku_blocked(blocked));
CREATE TABLE IF NOT EXISTS watch_histories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), user_id BIGINT UNSIGNED NOT NULL, video_id BIGINT UNSIGNED NOT NULL, position INT NOT NULL DEFAULT 0, UNIQUE KEY idx_watch_history(user_id, video_id));
CREATE TABLE IF NOT EXISTS watch_laters (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), user_id BIGINT UNSIGNED NOT NULL, video_id BIGINT UNSIGNED NOT NULL, UNIQUE KEY idx_watch_later(user_id, video_id));
CREATE TABLE IF NOT EXISTS live_rooms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), title VARCHAR(200) NOT NULL, cover_url VARCHAR(500), stream_key VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'idle', owner_id BIGINT UNSIGNED NOT NULL, viewer_count BIGINT NOT NULL DEFAULT 0, viewer_peak BIGINT NOT NULL DEFAULT 0, like_count BIGINT NOT NULL DEFAULT 0, gift_value BIGINT NOT NULL DEFAULT 0, chat_mode VARCHAR(20) NOT NULL DEFAULT 'everyone', slow_mode_seconds INT NOT NULL DEFAULT 0, pinned_message VARCHAR(500), started_at DATETIME(3), ended_at DATETIME(3), UNIQUE KEY idx_live_rooms_stream_key(stream_key), UNIQUE KEY idx_live_rooms_owner_id(owner_id), KEY idx_live_rooms_status(status));
CREATE TABLE IF NOT EXISTS live_schedules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), title VARCHAR(200) NOT NULL, cover_url VARCHAR(500), scheduled_at DATETIME(3) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', reminder_count BIGINT NOT NULL DEFAULT 0, owner_id BIGINT UNSIGNED NOT NULL, KEY idx_live_schedules_scheduled_at(scheduled_at), KEY idx_live_schedules_status(status), KEY idx_live_schedules_owner_id(owner_id));
CREATE TABLE IF NOT EXISTS live_reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), schedule_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, UNIQUE KEY idx_live_reservation(schedule_id, user_id));
CREATE TABLE IF NOT EXISTS live_gifts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), room_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, gift_key VARCHAR(30) NOT NULL, name VARCHAR(40) NOT NULL, count INT NOT NULL, value BIGINT NOT NULL, message VARCHAR(500), KEY idx_live_gifts_room_id(room_id), KEY idx_live_gifts_user_id(user_id));
CREATE TABLE IF NOT EXISTS live_likes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), room_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, UNIQUE KEY idx_live_like(room_id, user_id));
CREATE TABLE IF NOT EXISTS super_chats (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), room_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, gift_id BIGINT UNSIGNED NOT NULL, content VARCHAR(500) NOT NULL, display_seconds INT NOT NULL, UNIQUE KEY idx_super_chats_gift_id(gift_id));
CREATE TABLE IF NOT EXISTS live_interactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(3), updated_at DATETIME(3), deleted_at DATETIME(3), room_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(20) NOT NULL, value BIGINT NOT NULL DEFAULT 0, UNIQUE KEY idx_live_interaction(room_id, user_id, kind));
